<?php use App\Filings; $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><div><a class="small" href="/admin/filings">← Filings</a><h1><?= e(Filings::TYPE_LABELS[$f['filing_type']]) ?> — <?= e($f['jurisdiction']) ?></h1><span class="small muted"><?= e($f['number']) ?> · <a href="/admin/customers/<?= (int)$c['id'] ?>"><?= e($c['name'] ?: $c['email']) ?></a><?= $proj ? ' · <a href="/admin/projects/' . e($proj['number']) . '">' . e($proj['number']) . '</a>' : '' ?> · channel: <?= e($channel->automatic() ? 'API (automatic)' : 'assisted portal filing') ?></span></div><?php $badge($f['status']); ?></div>
<div class="grid g2" style="align-items:start"><div>
  <div class="panel"><h2>Submission gates</h2><?php foreach ($gates as $g => [$pass, $why]): ?><div class="row spread small" style="padding:4px 0"><span><?= e(label($g)) ?></span><?= $pass ? '<span class="badge b-green">pass</span>' : '<span class="badge b-red">' . e($why) . '</span>' ?></div><?php endforeach; ?>
    <?php if (!empty($v['errors'])): ?><div class="alert alert-error small" style="margin-top:10px"><?php foreach ($v['errors'] as $er): ?><div><?= e($er) ?></div><?php endforeach; ?></div><?php endif; ?>
    <?php if (!empty($v['warnings'])): ?><div class="alert alert-warn small"><?php foreach ($v['warnings'] as $wr): ?><div><?= e($wr) ?></div><?php endforeach; ?></div><?php endif; ?>
    <?php if (in_array($f['status'], ['authorized', 'in_review', 'awaiting_approval', 'rejected'], true)): ?><form method="post" action="/admin/filings/<?= e($f['number']) ?>" data-confirm="Submit this filing to the registry now?"><?= App\Csrf::field() ?><input type="hidden" name="action" value="submit"><button class="btn btn-primary btn-sm">Submit now</button></form><?php endif; ?></div>
  <?php if (in_array($f['status'], ['ready_to_file', 'submitted', 'awaiting_approval', 'authorized', 'rejected'], true)): ?>
  <div class="panel"><h2>Record the registry's decision</h2><p class="small muted">After filing on <a href="<?= e(Filings::JURISDICTIONS[$f['jurisdiction']][1]) ?>" target="_blank" rel="noopener"><?= e(Filings::JURISDICTIONS[$f['jurisdiction']][0]) ?></a>, record the outcome. The customer is notified and the project advances automatically.</p>
    <form method="post" enctype="multipart/form-data" action="/admin/filings/<?= e($f['number']) ?>" class="stack"><?= App\Csrf::field() ?><input type="hidden" name="action" value="accepted"><input type="text" name="registry_number" placeholder="Corporation / registration number" required><input type="file" name="file" accept=".pdf,.png,.jpg"><button class="btn btn-success btn-sm">Accepted — deliver to customer</button></form>
    <form method="post" action="/admin/filings/<?= e($f['number']) ?>" class="row" style="margin-top:10px"><?= App\Csrf::field() ?><input type="hidden" name="action" value="rejected"><input type="text" name="reason" placeholder="Registry's reason" style="flex:1" required><button class="btn btn-ghost btn-sm">Rejected</button></form></div><?php endif; ?>
  <div class="panel"><h2>History</h2><ul class="timeline"><?php foreach ($events as $ev): ?><li><time><?= e($ev['created_at']) ?> · <?= e($ev['actor']) ?></time><b><?= e(label($ev['kind'])) ?></b> <?= e($ev['detail']) ?></li><?php endforeach; ?></ul></div>
</div>
<div class="panel"><div class="row spread"><h2 style="margin:0">Filing sheet</h2><button class="btn btn-ghost btn-sm" type="button" data-copy="#sheet">Copy</button></div><pre id="sheet" class="sheet" style="margin-top:12px"><?= e($sheet) ?></pre>
  <p class="small muted">Authorization: <?= $f['auth_signer'] ? e($f['auth_signer']) . ' (' . e($f['auth_capacity']) . ') · ' . e($f['authorized_at']) . ' UTC · IP ' . e($f['auth_ip']) . ' · hash ' . e(substr((string)$f['auth_hash'], 0, 16)) : 'not signed' ?></p>
  <?php if (!in_array($f['status'], ['completed', 'cancelled', 'submitted'], true)): ?><form method="post" action="/admin/filings/<?= e($f['number']) ?>" data-confirm="Cancel this filing?"><?= App\Csrf::field() ?><input type="hidden" name="action" value="cancel"><button class="btn btn-ghost btn-sm">Cancel filing</button></form><?php endif; ?></div></div>
